import{_ as i,l,o as e,c as n,v as t,p as s,x as o,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"蜜罐","description":"","frontmatter":{"title":"蜜罐","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/honeypot.md","filePath":"cs/honeypot.md","lastUpdated":1789023840000}'),c={name:"cs/honeypot.md"};function _(m,a,E,u,f,A){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="蜜罐" tabindex="-1">蜜罐 <a class="header-anchor" href="#蜜罐" aria-label="Permalink to &quot;蜜罐&quot;">​</a></h1><div class="epigraph"><p>蜜罐是故意可发现的假系统：连上它的流量默认高可疑。它换来情报与低误报，前提是隔离足够，不被当成跳板打进真网。</p><footer>—— 据 Spitzner, *Honeypots*；Lance Spitzner 对蜜网的实践陈述</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/ids-rules">规则</a>误报高。缺口是<strong>高置信触点</strong>：没人该访问的地址。本课讲隔离与情报用途，不把蜜罐当诱捕违法的操作手册。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>规则对扫描噪声吵。蜜罐：低交互模拟服务，高交互真系统但隔离。缺口是逃逸与污染：蜜罐被占则成跳板。</p><h3 id="法律与伦理" tabindex="-1">法律与伦理 <a class="header-anchor" href="#法律与伦理" aria-label="Permalink to &quot;法律与伦理&quot;">​</a></h3><p>观测要符合政策。本课不讨论诱捕执法。</p><p><span class="marginnote">Spitzner。禁止用蜜罐数据去报复。DDoS 下一课换可用性轴。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层交互。日志外送、禁出站。对照 IDS：蜜罐事件默认真，仍要防误触（扫描自己）。</p>',12)),(e(),s(h,null,{default:o(()=>[d(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAKE%5B%22%E5%81%87%E6%9C%8D%E5%8A%A1%22%5D%20--%3E%20HIT%5B%22%E8%BF%9E%E6%8E%A5%E5%8D%B3%E5%8F%AF%E7%96%91%22%5D%0A%20%20HIT%20--%3E%20LOG%5B%22%E5%A4%96%E9%80%81%E6%97%A5%E5%BF%97%22%5D%0A%20%20FAKE%20--%3E%20ISO%5B%22%E7%A6%81%E5%87%BA%E7%AB%99%E9%98%B2%E8%B7%B3%E6%9D%BF%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>欺骗服务观测。不替代补丁。DDoS 下一课是可用性洪水，蜜罐帮不上容量。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写高交互逃逸。DDoS 缓解下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>规则吵；蜜罐触点默认可疑。</li><li>隔离与禁出站是前提。</li><li>换情报，不换容量。</li><li>下一课 DDoS 缓解。</li><li>出处：Spitzner, <em>Honeypots</em>。</li></ul>',8))])}const b=i(c,[["render",_]]);export{S as __pageData,b as default};
